            "title": "Proteção não depende de você sentir medo suficiente",
            "text": "Pessoas reagem de formas diferentes a situações difíceis: podem sentir medo, raiva, confusão ou pouca emoção naquele momento. Nenhuma nota subjetiva autoriza concluir que a interação é segura. Considere histórico e condutas concretas. Você decide quanto registrar e compartilhar, especialmente se alguém acessa seu aparelho. Esta jornada pode ajudar a entender uma necessidade, mas não monitora risco ou oferece mediação de violência. Se houver perigo imediato, procure ajuda direta; concluir uma ficha ou ensaiar uma conversa não é a prioridade."
